let tenants=[],editingId=-1;const loadTenants=()=>{$("#tenantTable").hide(),$("#loading").show(),api.tenants.get().success(e=>{tenants=e,$("#loading").hide(),$("#tenantTable").show();const t=$("#tenantTable tbody").empty();$.each(tenants,(n,a)=>{const s=$("<tr>");s.append($("<td>").text(a.name)),s.append($("<td>").text(moment(a.created_at).format("MMMM Do YYYY, h:mm:ss a")));const o=$("<div class='pull-right'>");o.append($("<button class='btn btn-primary edit-button'>").attr("data-tenant-id",a.id).html("<i class='fa fa-pencil'></i>")),o.append(" "),o.append($("<button class='btn btn-danger delete-button'>").attr("data-tenant-id",a.id).html("<i class='fa fa-trash-o'></i>")),s.append($("<td>").append(o)),t.append(s)})}).error(()=>errorFlash("Error fetching tenants"))},saveTenant=()=>{const e=$("#name").val();editingId===-1?api.tenants.post({name:e}).success(()=>{successFlash("Tenant created"),$("#modal").modal("hide"),loadTenants()}).error(t=>modalError(t.responseJSON.message)):api.tenantId.put({id:editingId,name:e}).success(()=>{successFlash("Tenant updated"),$("#modal").modal("hide"),loadTenants()}).error(t=>modalError(t.responseJSON.message))},editTenant=e=>{if(editingId=e,$("#modal\\.flashes").empty(),e===-1)$("#tenantModalLabel").text("New Tenant"),$("#name").val("");else{const t=tenants.find(n=>n.id===e);$("#tenantModalLabel").text("Edit Tenant"),$("#name").val(t?t.name:"")}$("#modal").modal("show")},deleteTenant=e=>{const t=tenants.find(n=>n.id===e);Swal.fire({title:"Are you sure?",text:"Delete the tenant "+escapeHtml(t.name)+"? Its users and teams must be removed first.",type:"warning",showCancelButton:!0,confirmButtonText:"Delete",confirmButtonColor:"#428bca",reverseButtons:!0,preConfirm:()=>new Promise((n,a)=>{api.tenantId.delete(e).success(()=>n()).error(s=>a(s.responseJSON.message))}).catch(n=>Swal.showValidationMessage(n))}).then(n=>{n.value&&(Swal.fire("Tenant Deleted!","","success"),loadTenants())})};$(document).ready(function(){loadTenants(),$("#new_button").click(()=>editTenant(-1)),$("#modalSubmit").click(saveTenant),$("#tenantTable").on("click",".edit-button",function(){editTenant(parseInt($(this).attr("data-tenant-id"),10))}),$("#tenantTable").on("click",".delete-button",function(){deleteTenant(parseInt($(this).attr("data-tenant-id"),10))})});
